def primeNumberGenerator(n):
    prime = [True for _ in range(n+1)]
    prime[0] = False
    prime[1] = False
    for p in range(2, n+1):
        if prime[p] == True:
            for i in range(2*p, n+1, p):
                prime[i] = False

    prime_nums = []
    for i in range(n+1):
        if prime[i] == True:
            prime_nums.append(i)

    return prime_nums

