def is_prime(num):

    # Base case
    if num == 1:
        return False
    elif num == 2:
        return True
    elif num % 2 == 0:
        return False

    # Iterate from 3 to the sqrt of number
    i = 3
    while(i * i <= num):

        if num % i == 0:
            return False
        i = i + 2

    return True

