def quickSort(arr): 
    less, equal, greater = [], [], [] 
    if len(arr) > 1: 
        pivot = arr[0] 
        for x in arr: 
            if x < pivot: 
                less.append(x) 
            elif x == pivot: 
                equal.append(x) 
            else: 
                greater.append(x) 
        return quickSort(less) + equal + quickSort(greater) 
    else:  
        return arr 

