def longest_common_prefix(st):
    if len(st) == 0: return ''

    first_word = st[0]
    prefix = ''
    for i in range(len(first_word)):
        for w in range(1, len(st)):
            if i >= len(st[w]) or st[w][i] != first_word[i]:
                return prefix
        prefix += first_word[i]

    return prefix

