        current = frontier.pop(0) 
        if current.puzz == [[1,2,3],[4,5,6],[7,8,0]]:
            return current
        visited.add(str(current.puzz)) 
        for nbr in current.get_neighbors():
            if str(nbr.puzz) not in visited: 
