class MaxHeap:
    def __init__(self):
        self.heap_list = [0]
        self.current_size = 0


    def perc_up(self, i):
        while i // 2 > 0:
            if self.heap_list[i] > self.heap_list[i // 2]:
               self.heap_list[i // 2], self.heap_list[i] = self.heap_list[i], self.heap_list[i // 2]
            i = i // 2

    def insert(self, k):
        self.heap_list.append(k)
        self.current_size = self.current_size + 1
        self.perc_up(self.current_size)

    def perc_down(self, i):
        while (i * 2) <= self.current_size:
            mc = self.max_child(i)
            if self.heap_list[i] < self.heap_list[mc]:
                self.heap_list[i], self.heap_list[mc] = self.heap_list[mc], self.heap_list[i]
            i = mc

    def max_child(self, i):
        if i * 2 + 1 > self.current_size:
            return i * 2
        else:
            if self.heap_list[i*2] > self.heap_list[i*2+1]:
                return i * 2
            else:
                return i * 2 + 1

    def delete_max(self):
        retval = self.heap_list[1]
        self.heap_list[1] = self.heap_list[self.current_size]
        self.current_size = self.current_size - 1
        self.heap_list.pop()
        self.perc_down(1)
        return retval

    def build_heap(self, alist):
        i = len(alist) // 2
        self.current_size = len(alist)
        self.heap_list = [0] + alist[:]
        while (i > 0):
            self.perc_down(i)
            i = i - 1

class BinarySearchTree:

 def __init__(self):
  self.root = None

 def add_node(self, value):
  if not self.root:
   self.root = Node(value)
  else: 
   self._add_node(self.root, value)

 def _add_node(self, node, value):
  if value <= node.value:
   if node.left:
    self._add_node(node.left, value)
   else:
    node.left = Node(value)
  else:
   if node.right:
    self._add_node(node.right, value)
   else:
    node.right = Node(value)

 def search(self, value):
  return self._search(self.root, value)

 def _search(self, node, value):
  if node is None:
   return False
  if node.value == value:
   return True
  else:
   if value <= node.value:
    return self._search(node.left, value)
   else: 
    return self._search(node.right, value)

 def get_size(self):
  return self._get_size(self.root)

 def _get_size(self, node):
  if not node:
   return 0
  return self._get_size(node.left) + 1 + self._get_size(node.right)

