def compute_levenshtein_distance(a, b): 
    n = len(a)
    m = len(b)
    d = [[0 for i in range(m + 1)] for j in range(n + 1)] 

    for i in range(n + 1): 
        for j in range(m + 1): 
            if i == 0:
                d[i][j] = j
            elif j == 0:
                d[i][j] = i
            elif a[i-1] == b[j-1]: 
                d[i][j] = d[i-1][j-1]
            else: 
                d[i][j] = min(d[i-1][j], d[i][j-1], d[i-1][j-1]) + 1   
    return d[n][m]

def longest_substring(string, k):
    start, distinct, max_length = 0, 0, 0
    frequency = {}
    for end in range(len(string)):
        frequency[string[end]] = frequency.get(string[end], 0) + 1
        if frequency[string[end]] == 1:
            distinct += 1

        while distinct > k:
            frequency[string[start]] -= 1
            if frequency[string[start]] == 0:
                distinct -= 1
            start += 1

        max_length = max(max_length, end - start + 1)
    return max_length

