def punctuate(text):
    text = text.strip()
    if not text.endswith('.'):
        text += '.'
    if not text.startswith(tuple('ABCDEFGHIJKLMNOPQRSTUVWXYZ')):
        text = text[0].upper() + text[1:]
    for char in ['!', '?', ':', ';', ',', '"']:
        if char in text:
            text = text[:-1] + char + ' '
    return text

