    for x in range(len(input_list)-1):
        min_val = x
        for y in range(x+1, len(input_list)):
            if input_list[min_val] > input_list[y]:
                min_val = y
        input_list[x], input_list[min_val] = input_list[min_val], input_list[x]
    return input_list

