def caesar_cipher(plaintext, caesar_key):
    ciphertext = ""

    for char in plaintext:
        if char.isalpha():
            ascii_char = ord(char) - caesar_key
            if ascii_char < 97:
                ascii_char += 26
            ciphertext += chr(ascii_char)
        else:
            ciphertext += char

    return ciphertext

