class StatisticOperation():
    def __init__(self, data):
        self.__data = data 

    def get_average(self):
        total = 0.0 
        for elem in self.__data:
            total += elem 
        return total / len(self.__data)

    def get_median(self):
        self.__data.sort()
        return self.__data[len(self.__data) // 2] 

    def get_mode(self): 
        data_map = {}
        best_mode = self.__data[0]
        mode_max_count = 0
        for elem in self.__data:
            if elem in data_map: 
                data_map[elem] += 1
                if data_map[elem] > mode_max_count:
                    mode_max_count = data_map[elem]
                    best_mode = elem
            else:
                data_map[elem] = 1

        return best_mode

