def is_isbn_valid(isbn):
    isbn = isbn.replace("-", "")
    if len(isbn) != 10:
        return False

    sum = 0
    factor = 10

    for i in range(len(isbn)):
        if isbn[i].isdigit():
            sum += int(isbn[i]) * factor
        elif isbn[i].upper() == 'X':
            sum += 10 * factor
        else:
            return False
        factor -= 1

    if sum % 11 == 0:
        return True
    else:
        return False

def compare_strings(s1, s2):
 m = len(s1)
 n = len(s2)

 # Create a table to store results of subproblems
 dp = [[0 for x in range(n + 1)] for x in range(m + 1)]

 # Fill d[][] in bottom up manner
 for i in range(m + 1):
  for j in range(n + 1):
   if i == 0 or j == 0:
    dp[i][j] = 0
   elif s1[i - 1] == s2[j - 1]:
    dp[i][j] = 1 + dp[i - 1][j - 1]
   else:
    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

 # LCS will be last entry in the lookup table
 return dp[m][n]

def merge_sorted_lists(listA, listB): 
    merged_list = []
    ptrA = 0
    ptrB = 0
    while ptrA < len(listA) and ptrB < len(listB): 
        if listA[ptrA] <= listB[ptrB]: 
            merged_list.append(listA[ptrA]) 
            ptrA += 1
        else: 
            merged_list.append(listB[ptrB]) 
            ptrB += 1
    while ptrA < len(listA): 
        merged_list.append(listA[ptrA]) 
        ptrA += 1
    while ptrB < len(listB):
