import re

def score_sentiment(text, lexicon):
    # Convert text to lowercase
    text = text.lower()

    # Create a score
    score = 0
    for word in re.findall(r"\w+", text):
        if word in lexicon:
            score += lexicon[word]
    score = float(score) / len(text)

    # Convert score to 0-10
    score = score * 10

    # Return score
    return round(score, 2)

