def mode(numbers):
    max_freq = 0
    modes = []
    for num in set(numbers):
        count = numbers.count(num)
        if count > max_freq:
            modes.clear()
            modes.append(num)
            max_freq = count
        elif count == max_freq and num not in modes:
            modes.append(num)
    return modes

