def fuzzy_search(text, word):
    matches = set()
    for i in range(len(text)-len(word)+1):
        if text[i:i+len(word)] == word:
            matches.add(word)

        elif all(text[i+j] == c or text[i+j] == '*' for j, c in enumerate(word)):
            matches.add(text[i:i+len(word)])

    return matches

def search(sorted_list, item):
    low = 0
    high = len(sorted_list) - 1
    found = False

    while low <= high and not found:
        mid = (low + high) // 2
        if sorted_list[mid] == item:
            found = True
        else:
            if item < sorted_list[mid]:
                high = mid - 1
            else:
                low = mid + 1
    return found

