  def helper(i, j):
    if i >= j:
      return
    s = nums[i] + nums[j]
    if s == target:
      foundPairs.add((nums[i], nums[j]))
    if s >= target:
      helper(i, j-1)
    else:
      helper(i+1, j)
  helper(0, len(nums)-1)
  return foundPairs

