"""
Create a Python decorator that counts the number of times a given 
function is called.
"""

def counter_decorator(func):
    count = 0

    def wrapper(*args, **kwargs):
        nonlocal count
        count += 1
        print(f'{func.__name__} has been called {count} times!')
        return func(*args, **kwargs)

    return wrapper

@counter_decorator
def random_function():
    pass

