def find_longest_substring(string):
    seenChars = set()
    longestSubstring = ''
    currentSubstring = ''

    for char in string:
        if char not in seenChars:
            seenChars.add(char)
            currentSubstring += char

            if len(currentSubstring) > len(longestSubstring):
                longestSubstring = currentSubstring
        else:
            seenChars.clear()
            currentSubstring = ''

    return longestSubstring

def isAnagramSubstring(string, substring):
    if len(substring) > len(string):
        return False

    chars = {}

    for char in string[:len(substring)]:
        if char in chars:
            chars[char] += 1
        else:
            chars[char] = 1

    for char in substring:
        if char not in chars or chars[char] == 0:
            return False
        else:
            chars[char] -= 1

    return True

