class Matrix(object):
    def __init__(self, m, n, data=0):
        self.m = m
        self.n = n
        self.data = data

    def __repr__(self):
        return "Matrix({}, {}, {})".format(self.m, self.n, self.data)

    def add(self, other):
        if not isinstance(other, Matrix) or (self.m != other.m) or (self.n != other.n):
            raise ValueError("Incompatible shapes for addition")

        dataList = [[0] * self.n for size in range(self.m)]
        for x in range(self.m):
            for y in range(self.n):
                dataList[x][y] = self.data[x][y] + other.data[x][y]

        return Matrix(self.m, self.n, dataList)

    def mul(self, other):
        if not isinstance(other, Matrix) or (self.m != other.n):
            raise ValueError("Incompatible shapes for multiplication")

        dataList = [[0] * other.n for size in range(self.m)]
        for x in range(self.m):
            for y in range(other.n):
                dataList[x][y] = sum(self.data[x][i] * other.data[i][y] for i in range(self.n))

        return Matrix(self.m, other.n, dataList)

