"""
Create a program in python that encrypts a string using the Caesar Cipher.
"""

def encrypt(string, shift): 
    cipher = '' 
    for char in string: 
        if char == ' ': 
            cipher = cipher + char 
        elif char.isupper(): 
            cipher = cipher + chr((ord(char) + shift - 65) % 26 + 65) 
        else: 
            cipher = cipher + chr((ord(char) + shift - 97) % 26 + 97) 
    return cipher

def permutations(string):
  # base case
  if len(string) <= 1:
    return set([string])

  # recursive case
  else:
    perms = permutations(string[1:])
    char = string[0]
    result = set()
    for perm in perms:
      for i in range(len(perm)+1):
        result.add(perm[:i] + char + perm[i:])
    return result

