def mode(nums):
    nums.sort()
    max_count = 1
    mode = nums[0]
    current_count = 1
    for i in range(1, len(nums)):
        if nums[i] == nums[i-1]: 
            current_count += 1
            if current_count > max_count:
                max_count = current_count 
                mode = nums[i]
        else:
            current_count = 1

    return mode

