    solutions = []
    #recursive solution
    def find_combos(solution, index):
        if sum(solution) == target:
            solutions.append(solution)
        elif sum(solution) < target:
            for i in range(index, len(numbers)):
               find_combos(solution + [numbers[i]], i)
    find_combos([], 0)
    return solutions

