def RGB_to_HSL(RGBList):
    output = []
    for color in RGBList:
        r = color[0]/255
        g = color[1]/255
        b = color[2]/255
        c_max = max(r, g, b)
        c_min = min(r, g, b)
        delta = c_max - c_min

        h = 0
        if delta == 0:
            h = 0
        elif c_max == r:
            h = 60 * (((g - b)/delta) % 6)
        elif c_max == g:
            h = 60 * (((b - r)/delta) + 2)
        elif c_max == b:
            h = 60 * (((r - g)/delta) + 4)

        l = (c_max + c_min)/2

        s = 0
        if delta == 0:
            s = 0
        else:
            s = delta/(1 - abs((2 * l) - 1))

        output.append([h,s,l])
    return output

def max_nested_depth(dictionary):
    max_depth = 0
    stack = []
    stack.append((dictionary, 1))

    while len(stack) > 0:
        item, depth = stack.pop()
        if depth > max_depth:
            max_depth = depth
        if type(item) is dict:
            for value in item.values():
                stack.append((value, depth+1))

    return max_depth

