def permutations(items):
  if len(items) == 0:
    return [[]]

  permutations_list = []

  for i in range(len(items)):
    items_copy = items.copy()
    item = items_copy.pop(i)
    permutations_partial = permutations(items_copy)

    for j in range(len(permutations_partial)):
      permutations_partial[j] = [item] + permutations_partial[j] 

    permutations_list.extend(permutations_partial)

  return permutations_list

