class Neural_Network:
    def __init__(self, learning_rate=0.01):
        self.learning_rate = learning_rate

    def sgd(self, values, target):
        guess = sum(values)*self.learning_rate

        gradients = [(2 * (guess - target)) for value in values]

        for gradient_index in range(len(gradients)):
            values[gradient_index] -= gradients[gradient_index] * self.learning_rate
        return values

