def edit_distance(str1, str2): 

    # Initialize the DP matrix 
    m = len(str1) + 1
    n = len(str2) + 1
    dp_matrix = [[0 for x in range(n)] for x in range(m)] 

    for i in range(m): 
        for j in range(n): 
            if i == 0: 
                dp_matrix[i][j] = j    # Min. operations = j 
            elif j == 0: 
                dp_matrix[i][j] = i    # Min. operations = i 

            # If characters match 
            elif str1[i-1] == str2[j-1]: 
                dp_matrix[i][j] = dp_matrix[i-1][j-1] 

            # If characters don't match 
            else: 
                dp_matrix[i][j] = 1 + min(dp_matrix[i][j-1],        # Insert 
                                          dp_matrix[i-1][j],        # Remove 
                                          dp_matrix[i-1][j-1])    # Replace 

    return dp_matrix[m-1][n-1]

def find_frequent_words(words):
    word_counts = {}
    for word in words:
        if word in word_counts:
            word_counts[word] += 1
        else:
            word_counts[word] = 1

    max_word_count = 0
    frequent_words = []
    for word, count in word_counts.items():
        if count > max_word_count:
            frequent_words = [word]
            max_word_count = count
        elif count == max_word_count:
            frequent_words.append(word)

    return frequent_words

