def merge_arrays(arr1, arr2):
    merged_array = []

    # While both arrays have elements
    while len(arr1) and len(arr2):
        if arr1[0] < arr2[0]:
            merged_array.append(arr1.pop(0))
        else:
            merged_array.append(arr2.pop(0))

    # If one of the array still has elements
    while len(arr1):
        merged_array.append(arr1.pop(0))

    while len(arr2):
        merged_array.append(arr2.pop(0))
    return merged_array

