def multiply_matrices(A, B):
    if len(A[0]) != len(B):
        return "Matrices can't be multiplied!"

    # create a matrix of zeros
    multiplied_matrix = [[0 for row in range(len(B[0]))] for col in range(len(A))]

    # iterate through rows of first matrix
    for i in range(len(A)):
        # iterate through columns of second matrix
        for j in range(len(B[0])):
            # iterate through rows of second matrix
            for k in range(len(B)):
