def longest_palindromic_subsequence(string):
    n = len(string)
    dp = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1
    for i in range(n-1):
        if string[i] == string[i+1]:
            dp[i][i+1] = 2
    for l in range(3, n+1):
        for i in range(n-l+1):
            j = i+l-1
            if string[i] == string[j]:
                dp[i][j] = dp[i+1][j-1] + 2
            else:
                dp[i][j] = max(dp[i][j-1], dp[i+1][j])
    return dp[0][n-1]

def max_sum(arr, forbidden_idx):
    max_sum = 0

    # Calculate the max sum without the forbidden index
    for i in range(len(arr)):
        if i == forbidden_idx:
            continue
        max_sum += arr[i]

    # Calculate the max sum with the forbidden index
    for i in range(len(arr)):
        if i == forbidden_idx:
            continue
        new_sum = max_sum - arr[i] + arr[forbidden_idx]
        if new_sum > max_sum:
            max_sum = new_sum

    return max_sum

