def largest_common_substring(str1, str2):
    # Create a 2D list to store the LCS lengths
    lengths = [[0 for _ in range(len(str2)+1)] for _ in range(len(str1)+1)]

    # Fill the table
    for i in range(1, len(str1)+1):
        for j in range(1, len(str2)+1):
            if str1[i-1] == str2[j-1]:
                lengths[i][j] = lengths[i-1][j-1] + 1
            else:
                lengths[i][j] = max(lengths[i-1][j], lengths[i][j-1])

    # Read the substring out from from the table
    result = ""
    x, y = len(str1), len(str2)
    while x != 0 and y != 0:
        if lengths[x][y] == lengths[x-1][y]:
            x -= 1
        elif lengths[x][y] == lengths[x][y-1]:
            y -= 1
        else:
            result = str1[x-1] + result
            x -= 1
            y -= 1

    return result

