def rotate_rectangle(rectangle):
    n = len(rectangle)
    for i in range(n):
        for j in range(i + 1, n):
           rectangle[i][j], rectangle[j][i] = rectangle[j][i], rectangle[i][j]

    for row in rectangle:
        row.reverse()

