def is_valid_triangle(a, b, c): 

    # triangle should have 3 sides 
    if a + b <= c or a + c <= b or b + c <= a: 
        return False

    # sum of any two side should always be greater than third side 
    if a + b > c and a + c > b and b + c > a: 
